<script setup lang="ts">
import { onMounted, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import ProductCard from '../components/ProductCard.vue'
import LoadingState from '../components/LoadingState.vue'
import type { Category, PageResult, Product } from '../types'
import { api } from '../services/api'
const route = useRoute(); const router = useRouter(); const categories = ref<Category[]>([]); const products = ref<Product[]>([]); const loading = ref(true); const error = ref(''); const page = ref(1); const pageSize = 12; const total = ref(0)
const search = ref(String(route.query.search ?? '')); const category = ref(String(route.query.category ?? '')); const sort = ref(String(route.query.sort ?? 'popular')); const minPrice = ref(String(route.query.min_price ?? '')); const maxPrice = ref(String(route.query.max_price ?? ''))
async function load() { loading.value = true; error.value = ''; try { const params = new URLSearchParams({page:String(page.value),page_size:String(pageSize),sort:sort.value}); if(search.value.trim()) params.set('search',search.value.trim()); if(category.value) params.set('category',category.value); if(minPrice.value) params.set('min_price',minPrice.value); if(maxPrice.value) params.set('max_price',maxPrice.value); const result = await api.get<PageResult<Product>>(`/api/v1/products?${params}`); products.value=result.items; total.value=result.pagination.total_items } catch(e) { error.value=e instanceof Error?e.message:'Gagal memuat produk' } finally { loading.value=false } }
function updateQuery() { router.replace({query:{...route.query, ...(search.value?{search:search.value}:{}), ...(category.value?{category:category.value}:{}), ...(minPrice.value?{min_price:minPrice.value}:{}), ...(maxPrice.value?{max_price:maxPrice.value}:{}), ...(sort.value?{sort:sort.value}:{}), page:String(page.value)}}); load() }
watch(() => route.query, q => { search.value=String(q.search??''); category.value=String(q.category??''); minPrice.value=String(q.min_price??''); maxPrice.value=String(q.max_price??''); sort.value=String(q.sort??'popular'); page.value=Number(q.page??1); load() })
onMounted(async()=>{ try{categories.value=await api.get<Category[]>('/api/v1/categories')}catch{}; await load() })
</script>
<template><section class="page-intro"><p class="eyebrow">TOKO NUSAMART</p><h1>Katalog produk</h1><p>Temukan barang yang cocok untuk kebutuhanmu.</p></section><div class="catalog-layout"><aside class="filter-panel"><h3>Filter produk</h3><form @submit.prevent="page=1;updateQuery()"><label class="field-label">Cari produk<input v-model="search" placeholder="Nama produk…" /></label><label class="field-label">Kategori<select v-model="category"><option value="">Semua kategori</option><option v-for="c in categories" :key="c.id" :value="c.slug">{{ c.name }}</option></select></label><div class="price-filter-grid"><label class="field-label">Harga minimum<input v-model="minPrice" type="number" min="0" placeholder="Rp 0"/></label><label class="field-label">Harga maksimum<input v-model="maxPrice" type="number" min="0" placeholder="Tanpa batas"/></label></div><label class="field-label">Urutkan<select v-model="sort"><option value="popular">Terpopuler</option><option value="newest">Terbaru</option><option value="price_asc">Harga terendah</option><option value="price_desc">Harga tertinggi</option><option value="rating">Rating tertinggi</option></select></label><button class="button-primary full-button">Terapkan filter</button><button type="button" class="button-secondary full-button" @click="search='';category='';sort='popular';page=1;updateQuery()">Reset filter</button></form></aside><div class="catalog-results"><div class="results-top"><span>{{ total }} produk ditemukan</span><span v-if="category">Kategori: {{ categories.find(c=>c.slug===category)?.name ?? category }}</span></div><p v-if="error" class="error-banner">{{ error }}</p><LoadingState v-else-if="loading"/><div v-else-if="products.length" class="product-grid"><ProductCard v-for="p in products" :key="p.id" :product="p"/></div><div v-else class="empty-state"><h3>Produk tidak ditemukan</h3><p>Coba ubah kata kunci atau filter pencarian.</p></div><div v-if="total>pageSize" class="pagination"><button class="button-secondary" :disabled="page<=1" @click="page--;updateQuery()">← Sebelumnya</button><span>Halaman {{ page }} dari {{ Math.ceil(total/pageSize) }}</span><button class="button-secondary" :disabled="page>=Math.ceil(total/pageSize)" @click="page++;updateQuery()">Berikutnya →</button></div></div></div></template>
